import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const repoRoot = path.resolve(import.meta.dirname, '..', '..');
const extensionDir = path.join(repoRoot, 'jobright_extension');
const outputFile = path.join(extensionDir, 'content.js');

// The copilot ships as one content script, so it carries the shared autofill engine with it.
export const CONTENT_SOURCES = [
  'core/form-discovery.js',
  'core/field-mapping.js',
  'core/field-writer.js',
  'core/copilot.js'
];

const HEADER = `/**
 * NextKin copilot content script.
 * Nextkinlife LLC
 *
 * Generated by scripts/tools/build-extension-content.mjs - edit the sources listed below.
 */

`;

export async function buildContentScript() {
  const parts = [];
  for (const source of CONTENT_SOURCES) {
    parts.push(await readFile(path.join(extensionDir, source), 'utf8'));
  }
  return HEADER + parts.join('\n');
}

const checkOnly = process.argv.includes('--check');
const bundled = await buildContentScript();

if (checkOnly) {
  let current = '';
  try {
    current = await readFile(outputFile, 'utf8');
  } catch {
    current = '';
  }
  if (current !== bundled) {
    console.error('jobright_extension/content.js is out of date. Run: node scripts/tools/build-extension-content.mjs');
    process.exit(1);
  }
  console.log('jobright_extension/content.js is up to date.');
} else {
  await writeFile(outputFile, bundled);
  console.log(`Wrote jobright_extension/content.js from ${CONTENT_SOURCES.length} sources.`);
}
